{
  "passageId": "corporate-law",
  "itemKey": "a",
  "form": "IN_PASSAGE",
  "situation": {
    "description": "지문의 무상 증자에 관한 설명에 적용할 값으로, 어느 주식회사의 증자 전 발행 주식 수를 1만 주, 모든 주식의 액면가를 1,000원으로 설정한다. 이 회사는 자본 잉여금 중 300만 원을 사용하여 무상 증자를 실시하며, 추가 발행하는 주식의 액면가도 1,000원이다. 이 무상 증자 외에 발행 주식 수나 액면가에 영향을 주는 변동은 없다.",
    "slotRef": "R3-S1",
    "bogiText": null
  },
  "usedRuleIds": [
    "R3",
    "R6"
  ],
  "steps": [
    {
      "n": 1,
      "given": "증자 전 발행된 총 주식 수는 10,000주이고, 주식의 액면가는 1,000원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "증자 전 자본금은 10,000주×1,000원=10,000,000원이다."
    },
    {
      "n": 2,
      "given": "무상 증자에 사용하는 자본 잉여금은 3,000,000원이다.",
      "ruleId": "R6",
      "ruleQuote": "주식회사는 무상 증자를 실시하여 자본 잉여금이나 이익 잉여금의 일부 혹은 전부에 해당하는 만큼의 주식을 추가로 발행하여 주주들에게 무상으로 분배한다.",
      "result": "자본 잉여금 3,000,000원에 해당하는 주식을 추가 발행하여 주주들에게 무상으로 분배한다."
    },
    {
      "n": 3,
      "given": "추가 발행할 주식에 해당하는 금액은 3,000,000원이고, 추가 발행 주식의 액면가는 1,000원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "추가 발행 주식 수는 3,000,000원÷1,000원=3,000주이다."
    },
    {
      "n": 4,
      "given": "증자 전 주식 수는 10,000주이고 추가 발행 주식 수는 3,000주이며, 모든 주식의 액면가는 1,000원이다. 증자 전 자본금은 10,000,000원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "증자 후 발행된 총 주식 수는 13,000주이고 자본금은 13,000주×1,000원=13,000,000원이다. 자본금은 증자 전보다 3,000,000원, 즉 30% 증가한다."
    }
  ],
  "derivedFacts": [
    {
      "id": "F1",
      "text": "이 회사의 무상 증자 전 자본금은 1,000만 원이다.",
      "fromSteps": [
        1
      ],
      "ifDifferent": "증자 전 주식 수가 같고 액면가가 2,000원이었다면 증자 전 자본금은 2,000만 원이 된다."
    },
    {
      "id": "F2",
      "text": "이번 무상 증자로 주주들에게 무상 분배되는 주식은 총 3,000주이다.",
      "fromSteps": [
        2,
        3
      ],
      "ifDifferent": "액면가가 같고 무상 증자에 사용하는 자본 잉여금이 200만 원이었다면 무상 분배되는 주식은 총 2,000주가 된다."
    },
    {
      "id": "F3",
      "text": "무상 증자를 마친 뒤 이 회사의 발행 주식 수는 총 13,000주이다.",
      "fromSteps": [
        3,
        4
      ],
      "ifDifferent": "증자 전 주식 수가 20,000주이고 나머지 조건이 같았다면 증자 후 발행 주식 수는 총 23,000주가 된다."
    },
    {
      "id": "F4",
      "text": "무상 증자 후 자본금은 1,300만 원으로, 증자 전보다 30% 증가한다.",
      "fromSteps": [
        1,
        4
      ],
      "ifDifferent": "다른 조건은 같고 무상 증자에 사용하는 자본 잉여금이 500만 원이었다면 증자 후 자본금은 1,500만 원으로 증자 전보다 50% 증가한다."
    }
  ],
  "selfCheck": "무상 증자에 쓰는 300만 원을 액면가 1,000원으로 나누어 추가 발행 주식 수 3,000주를 구하고, 증자 후 총 주식 수에 액면가를 곱해 자본금 1,300만 원을 확인했다. 각 결론은 설정한 값과 R3·R6에서 도출되며, 자본금 증가를 자산 총규모의 증가로 해석하지 않았다."
}

